urlset:
{%- for sitemap_entry in entries %}

        {{ sitemap_entry.permalink | escape_xml | safe }}
        {% if sitemap_entry.updated -%}
            {{ sitemap_entry.updated | date(format="%Y-%m-%dT%H:%M", timezone="Europe/Berlin") }}
        {%- elif sitemap_entry.date -%}
            {{ sitemap_entry.date | date(format="%Y-%m-%dT%H:%M", timezone="Europe/Berlin") }}
        {%- endif %}

{%- endfor %}
